package com.cafeteria.service.impl;
import com.cafeteria.dto.response.LoginResponse; import com.cafeteria.entity.User; import com.cafeteria.exception.InvalidOperationException; import com.cafeteria.repository.UserRepository; import com.cafeteria.service.AuthService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthServiceImpl implements AuthService{private final UserRepository repo;private final PasswordEncoder encoder;public AuthServiceImpl(UserRepository r,PasswordEncoder e){repo=r;encoder=e;}public LoginResponse login(String email,String password){User u=repo.findByEmailAndIsActiveTrue(email==null?"":email.trim().toLowerCase()).orElseThrow(()->new InvalidOperationException("Invalid email or password."));if(password==null||!encoder.matches(password,u.getPasswordHash()))throw new InvalidOperationException("Invalid email or password.");return new LoginResponse(u.getUserId(),u.getFullName(),u.getEmail(),u.getRole(),"Login successful");}}
